{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "1-NA-PP1, a tert-butyl-substituted amino-fused heteroaromatic, crossed the BBB after systemic administration and reached brain concentrations sufficient for target inhibition, supporting CNS access for the query's similar tert-butyl/aminoheteroaromatic core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "MTX-241F, an aminopyrimidine-fused heteroaromatic, achieved micromolar murine brain levels and was characterized as brain-penetrant, supporting the query's aminopyrimidine-fused scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A morpholine-containing pyrimidine analogue showed a brain/plasma ratio of 2.4 in rat, demonstrating that morpholine and polar heteroaromatic features do not preclude high brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "An aminopyrimidine-fused heteroaromatic with a tert-butyl-containing substituent had a brain/plasma AUC ratio of 2.2 and central Hsp90 engagement after oral dosing, supporting meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "SHP099, an aminopyrimidine with a basic amine, showed brain-plasma ratios >1 and efficacious brain concentrations in mice, supporting the query's aminopyrimidine/amine-containing chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A related anilino-pyrimidine morpholine amide had a low Bu/Pu ratio of 0.11, indicating poor brain penetration; however, this analogue contains an amide-linked morpholine and CF3-aniline not present in the query, and its lower transfer score reduces weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "CZC25146, an aminopyrimidine with a morpholine aniline, showed negligible brain penetration; however, it is a larger anilino-sulfonamide with additional polar/efflux liabilities not shared by the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the highest-transfer direct in vivo brain-penetration measurements for closely related aminopyrimidine/fused heteroaromatic/morpholine-containing kinase inhibitors consistently show meaningful CNS exposure (B/P >1-2.4, central target engagement), while the lower-transfer poor-penetration records involve additional liabilities (amide-linked morpholine, high lipophilicity, large anilino-sulfonamide) not present in the query. Physicochemical properties are within CNS-compatible ranges.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or efflux-transport measurement for the exact query molecule.",
    "P-gp/BCRP substrate status is unknown; TPSA and HBA are borderline high and could reduce passive permeability, but supportive analogues indicate this does not preclude adequate CNS exposure.",
    "The query's primary aromatic amine and morpholine may be transporter recognition motifs, but no experimental confirmation is available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

